import QRCode from 'qrcode';
// Generador de PDF basado en el HTML v5 validado.
// No requiere PowerPoint ni instalación de programas en la computadora del usuario.

const BASE_PDF = "";

export const FIXED = {
  officeHeader: 'SANTA MARIA DEL LORO 2-',
  cityState: 'HERMOSILLO, SONORA',
  cp: '00000',
  service: 'COMERCIAL',
  coverage: 'RC ECONOMICA M2',
  coverageDesc: 'DAÑOS A TERCEROS (MATERIALES)',
  rcBienes: 60000,
  deductible: 1500,
  primaDefault: 360.00,
  gastosDefault: 135.69,
  office: 'MOCHIS',
  locality: 'LOS MOCHIS',
  officePhone: '01 (668) 690 1476',
  officeAddress1: 'DEGOLLADO # 710 SUR. ES. CON CUAUHTEMOC. LOCAL # 4',
  officeAddress2: 'CENTRO MOCHIS',
  claimPhone: '668 144 0988'
};

function pad(n) { return String(n).padStart(2, '0'); }

const POLICY_TIMEZONE = process.env.POLICY_TIMEZONE || 'America/Hermosillo';

function zonedParts(now, timeZone = POLICY_TIMEZONE) {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });

  const parts = {};
  for (const item of formatter.formatToParts(now)) {
    if (item.type !== 'literal') parts[item.type] = item.value;
  }

  let hour = Number(parts.hour || 0);
  // Intl puede regresar 24 para medianoche en algunos entornos.
  if (hour === 24) hour = 0;

  return {
    day: Number(parts.day),
    month: Number(parts.month),
    year: Number(parts.year),
    hour,
    minute: Number(parts.minute),
    second: Number(parts.second)
  };
}

function nextYearDateString(z) {
  let day = z.day;
  const month = z.month;
  const year = z.year + 1;
  // Seguridad para 29 de febrero.
  if (month === 2 && day === 29) day = 28;
  return `${pad(day)}/${pad(month)}/${year}`;
}

function nowParts(now = new Date()) {
  const z = zonedParts(now, POLICY_TIMEZONE);
  const date = `${pad(z.day)}/${pad(z.month)}/${z.year}`;
  const nextDate = nextYearDateString(z);
  const time24 = `${pad(z.hour)}:${pad(z.minute)}:${pad(z.second)}`;

  // Se usa hora 24h para evitar que a. m. / p. m. se encime o se corte en el PDF.
  return { date, nextDate, time24, desde: `${date} ${time24}`, hasta: `${nextDate} ${time24}` };
}

export function money(v) {
  return Number(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function cleanUpper(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .trim()
    .toUpperCase();
}

function cleanVin(value) {
  // VIN solo debe llevar letras A-Z y números; se eliminan espacios, guiones y caracteres raros.
  return cleanUpper(value).replace(/[^A-Z0-9]/g, '');
}

export function buildQrPayload(policy) {
  // Texto exacto que se guarda dentro del QR.
  // Ejemplo:
  // ?cl=GILBERTO QUINTANA ANTELO,pol=SANTM 2-981,tt=575.0000,vig=26/03/2027,noser=1D7HU18N75S196937
  return `?cl=${policy.name || ''},pol=${policy.folio || ''},tt=${policy.totalQr || '0.0000'},vig=${policy.nextDate || ''},noser=${policy.vin || ''}`;
}

export function normalizePolicyInput(input, folioNumber, folioPrefix = 'SANTM 2-', now = new Date()) {
  const p = nowParts(now);
  const prima = FIXED.primaDefault;
  const gastos = FIXED.gastosDefault;
  const subtotal = Number((prima + gastos).toFixed(2));
  const iva = Number((subtotal * 0.16).toFixed(2));
  const total = Number((subtotal + iva).toFixed(2));
  const policy = {
    folio: `${folioPrefix}${folioNumber}`,
    officeHeader: FIXED.officeHeader,
    coverage: FIXED.coverage,
    date: p.date,
    nextDate: p.nextDate,
    desde: p.desde,
    hasta: p.hasta,
    hour: p.time24,
    name: cleanUpper(input.name),
    address: cleanUpper(input.address),
    cityState: FIXED.cityState,
    cp: FIXED.cp,
    phone: String(input.phone ?? '').replace(/\D/g, ''),
    auto: cleanUpper(input.auto),
    plates: '',
    service: FIXED.service,
    body: cleanUpper(input.body),
    modelYear: String(input.modelYear ?? '').trim(),
    vin: cleanVin(input.vin),
    coverageDesc: FIXED.coverageDesc,
    rc: money(FIXED.rcBienes),
    ded: money(FIXED.deductible),
    prima: money(prima),
    gastos: money(gastos),
    subtotal: money(subtotal),
    iva: money(iva),
    total: money(total),
    totalQr: total.toFixed(4),
    office: FIXED.office,
    locality: FIXED.locality,
    officePhone: FIXED.officePhone,
    officeAddress1: FIXED.officeAddress1,
    officeAddress2: FIXED.officeAddress2,
    claimPhone: FIXED.claimPhone,
    signPlace: `${FIXED.locality}, SINALOA`
  };
  policy.qrPayload = buildQrPayload(policy);
  return policy;
}

function latin1(s) {
  s = String(s ?? '').normalize('NFC')
    .replace(/[–—]/g, '-')
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"');
  let out = '';
  for (const ch of s) {
    const c = ch.charCodeAt(0);
    out += c <= 255 ? ch : '?';
  }
  return out;
}

function pdfEsc(s) {
  return latin1(s)
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)')
    .replace(/\r/g, '')
    .replace(/\n/g, ' ');
}

function addText(ops, text, x, y, size = 8.04, bold = true) {
  if (text === undefined || text === null || String(text) === '') return;
  const font = bold ? 'F1' : 'F2';
  ops.push(`BT /${font} ${size.toFixed(2)} Tf 0 g 1 0 0 1 ${x.toFixed(2)} ${y.toFixed(2)} Tm (${pdfEsc(text)}) Tj ET
`);
}

function addFixedText(ops, text, x, y, size = 7.85, bold = true, spacing = 5.20) {
  const s = String(text ?? '');
  if (!s) return;
  const font = bold ? 'F1' : 'F2';
  for (let i = 0; i < s.length; i++) {
    ops.push(`BT /${font} ${size.toFixed(2)} Tf 0 g 1 0 0 1 ${(x + i * spacing).toFixed(2)} ${y.toFixed(2)} Tm (${pdfEsc(s[i])}) Tj ET
`);
  }
}

function addFillRect(ops, x, y, w, h, r = 0.949, g = 0.949, b = 0.949) {
  ops.push(`q ${r} ${g} ${b} rg ${x.toFixed(2)} ${y.toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re f Q
`);
}

function addQrCode(ops, payload, x, y, size) {
  if (!payload) return;

  const qr = QRCode.create(String(payload), {
    errorCorrectionLevel: 'M'
  });

  const matrixSize = qr.modules.size;
  const data = qr.modules.data;
  const quiet = 4;
  const cell = size / (matrixSize + quiet * 2);

  // Tapa completamente el QR fijo de la plantilla antes de dibujar el nuevo.
  addFillRect(ops, x - 4, y - 4, size + 8, size + 8, 1, 1, 1);

  for (let row = 0; row < matrixSize; row++) {
    for (let col = 0; col < matrixSize; col++) {
      if (!data[row * matrixSize + col]) continue;

      const rx = x + (col + quiet) * cell;
      const ry = y + size - (row + quiet + 1) * cell;

      addFillRect(ops, rx, ry, cell + 0.04, cell + 0.04, 0, 0, 0);
    }
  }
}

