    addText(ops, f.coverage, 479.78, 689.57, 8.04, true);
    addText(ops, f.nextDate, 498.79, 669.00, 8.04, true);
    addText(ops, f.date, 498.79, 648.74, 8.04, true);
    addText(ops, f.desde, 470.57, 628.49, 8.04, true);
