    addText(ops, f.body, 194.78, 470.23, 8.04, true);
    addText(ops, f.modelYear, 367.01, 504.43, 8.04, true);
    // VIN / No. de serie: se mantiene compacto, sin espacios, con tamaño ligeramente menor
    // para que no se encime visualmente ni rebase el área debajo de "NO SE SERIE:".
    addFillRect(ops, 292.00, 462.00, 155.00, 16.00, 1, 1, 1);
